-- public.remove_participant
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();

-- Threads: announcement (A), group (G: coach, par1, par3), direct (D: par1 <-> par3)
set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000003') $$, '42501', null, 'anonymous cannot remove');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000003') $$, '42501', null, 'a parent cannot remove someone else');
select lives_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000001') $$, 'a parent can leave a group');
reset role; select set_config('request.jwt.claims', '{"sub":"aa000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000003') $$, 'the owner removes a participant');
select throws_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000003') $$, 'P0001', 'not_a_participant', 'removing a non-participant errors');
select throws_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','aa000000-0000-0000-0000-000000000001') $$, 'P0001', 'minor_group_needs_two_adults', 'cannot remove the second staff adult from a minor group');
select throws_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000c','bb000000-0000-0000-0000-000000000003') $$, '42501', null, 'cannot manage a direct thread you do not own as staff');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000003","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000c','bb000000-0000-0000-0000-000000000003') $$, 'P0001', 'not_a_group', 'cannot leave a direct thread');
reset role; select set_config('request.jwt.claims', '{"sub":"cc000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','cc000000-0000-0000-0000-000000000001') $$, 'a minor can leave a group');
reset role; select set_config('request.jwt.claims', '{"sub":"aa000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','aa000000-0000-0000-0000-000000000001') $$, 'once the minor left the staff rule no longer applies');
reset role; select set_config('request.jwt.claims', '{"sub":"dd000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select public.remove_participant('71000000-0000-0000-0000-00000000000b','bb000000-0000-0000-0000-000000000001') $$, '42501', null, 'another team cannot remove');
reset role;
select cmp_ok((select count(*)::int from public.audit_log where action='thread.remove_participant'), '=', 4, 'removals are audited');
reset role;
select * from finish();
rollback;
